% and carry the examples of the ISO/IEC 13211-1 standard and of the
% conformance testing framework of Peter Szabo and Peter Szeredi.
% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).

foo(X) :-
	Y is X * 2, throw(test(Y)).
bar(X) :-
	X = Y, throw(Y).
coo(X) :-
	throw(X).
car(X) :-
	X = 1, throw(X).
g :-
	catch(p, _B, write(h2)),
	coo(c).
p.
p :-
	throw(b).
q :-
	catch((true; throw(err)), E, write(E)),
	fail.
r(1).

v(iso_catch_3_01, true(Y == 10), (catch(foo(5), test(Y), true))).
v(iso_catch_3_02, true(Z == 3), (catch(bar(3), Z, true))).
v(iso_catch_3_03, true, (catch(true, _, 3))).
v(iso_catch_3_05, true(Y == 1), (catch(car(_X), Y, true))).
v(iso_catch_3_06, fail, (catch(number_chars(_X,['1',a,'0']), error(syntax_error(_),_), fail))).
v(lgt_catch_3_11, fail, (catch(fail, _, true))).
